    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

{"path": "/tmp/sv-929ff67813284cfe870490ac55bd04c3/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_929ff67813284cfe870490ac55bd04c3.Components.Pages.Settings
@using sv_929ff67813284cfe870490ac55bd04c3.Services

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (statusMessage is not null)
    {
        <div class="toast @(isError ? "error" : "success")">@statusMessage</div>
    }

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
            <span>🔑 Change Password</span>
            <span class="expand-icon">@(passwordPanelOpen ? "▼" : "▶")</span>
        </button>

        @if (passwordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="currentPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="newPassword" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="confirmPassword" class="form-control" />
                </div>
                <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@changingPassword">
                    @(changingPassword ? "Updating..." : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="twofa-section">
        <div class="twofa-header">
            <h3>Two-Factor Authentication</h3>
            <span class="status-indicator @(twoFactorEnabled ? "enabled" : "disabled")">
                @(twoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        <label class="toggle-item">
            <input type="checkbox" @bind="twoFactorEnabled" class="toggle-switch" />
            <span>Enable Two-Factor Authentication</span>
        </label>
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h3>Active Sessions</h3>
        @if (Settings?.Sessions is { Count: > 0 })
        {
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Settings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != currentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm"
                                            @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-session-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        }
        else
        {
            <p class="text-muted">No active sessions.</p>
        }
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (sessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h3>Revoke Session</h3>
                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                <div class="button-group">
                    <button class="btn btn-danger" @onclick="RevokeConfirmed" disabled="@revoking">
                        @(revoking ? "Revoking..." : "Revoke Session")
                    </button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool changingPassword;
    private bool twoFactorEnabled;

    private ActiveSession? sessionToRevoke;
    private bool revoking;
    private string? statusMessage;
    private bool isError;

    private string currentSessionId = "current";

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            twoFactorEnabled = Settings.TwoFactorEnabled;
            if (Settings.Sessions.Count > 0)
            {
                currentSessionId = Settings.Sessions[0].Id;
            }
        }
    }

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(newPassword))
        {
            ShowStatus("New password cannot be empty.", true);
            return;
        }
        if (newPassword != confirmPassword)
        {
            ShowStatus("Passwords do not match.", true);
            return;
        }

        changingPassword = true;
        await OnChangePassword.InvokeAsync((currentPassword, newPassword));
        changingPassword = false;
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        ShowStatus("Password updated successfully.", false);
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task RevokeConfirmed()
    {
        if (sessionToRevoke is null) return;
        revoking = true;
        await OnRevokeSession.InvokeAsync(sessionToRevoke.Id);
        revoking = false;
        ShowStatus($"Session on {sessionToRevoke.Device} revoked.", false);
        sessionToRevoke = null;
    }

    private void ShowStatus(string message, bool error)
    {
        statusMessage = message;
        isError = error;
        _ = HideStatusAfterDelay();
    }

    private async Task HideStatusAfterDelay()
    {
        await Task.Delay(3000);
        statusMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}
"}

{"path": "/tmp/sv-929ff67813284cfe870490ac55bd04c3/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_929ff67813284cfe870490ac55bd04c3.Components.Pages.Settings
@using sv_929ff67813284cfe870490ac55bd04c3.Services

<div class="settings-section">
    <h2>Appearance Settings</h2>

    @if (showSuccess)
    {
        <div class="toast success">Appearance settings saved!</div>
    }

    <!-- Theme Selector -->
    <div class="form-group">
        <label><strong>Theme</strong></label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-item">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(selectedTheme == theme)"
                           @onchange="() => selectedTheme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <!-- Font Size Selector -->
    <div class="form-group">
        <label><strong>Font Size</strong></label>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(selectedFontSize == size)"
                           @onchange="() => selectedFontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <!-- Language Dropdown -->
    <div class="form-group">
        <label for="language"><strong>Language</strong></label>
        <select id="language" @bind="selectedLanguage" class="form-control">
            <option value="en">English</option>
            <option value="es">Español</option>
            <option value="fr">Français</option>
            <option value="de">Deutsch</option>
            <option value="ja">日本語</option>
            <option value="zh">中文</option>
        </select>
    </div>

    <!-- Compact Mode -->
    <div class="form-group">
        <label class="toggle-item">
            <input type="checkbox" @bind="compactMode" class="toggle-switch" />
            <span><strong>Compact Mode</strong></span>
        </label>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p>This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>
            <button class="btn btn-primary btn-preview">Sample Button</button>
        </div>
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@saving">
            @(saving ? "Saving..." : "Save")
        </button>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "System";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;
    private bool saving;
    private bool showSuccess;

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            selectedTheme = Settings.Theme;
            selectedFontSize = Settings.FontSize;
            selectedLanguage = Settings.Language;
            compactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{selectedTheme.ToLowerInvariant()} preview-font-{selectedFontSize.ToLowerInvariant()}";
        if (compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        saving = true;
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);
        saving = false;
        showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

